data class Order(val units: Int, val loyaltyYears: Int, var discount: Double = 0.0)

// src/main/resources/rules/order.drl
// rule "Volume discount"
//   when $o: Order(units > 100, loyaltyYears > 2)
//   then modify($o) { setDiscount(0.10) }; end

val session: KieSession = container.newKieSession()
session.insert(Order(units = 250, loyaltyYears = 5))
session.fireAllRules()
session.dispose()

data class Rule<T>(val name: String, val matches: (T) -> Boolean, val apply: (T) -> T)

val rules = listOf(
    Rule<Order>("volume-discount", { it.units > 100 }, { it.copy(discount = 0.10) }),
    Rule<Order>("vip-shipping", { it.isVip }, { it.copy(freeShipping = true) }),
)

val priced = rules.fold(order) { acc, rule -> if (rule.matches(acc)) rule.apply(acc) else acc }
